import React, { useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter, Link, Navigate, Route, Routes, useLocation, useNavigate } from "react-router-dom";
import "./styles.css";

const API = "http://127.0.0.1:8000";

async function api(path, options = {}) {
  const headers = { "Content-Type": "application/json", ...(options.headers || {}) };
  const token = localStorage.getItem("token");
  if (token) headers.Authorization = `Bearer ${token}`;
  const response = await fetch(`${API}${path}`, { ...options, headers });
  const data = await response.json().catch(() => ({ detail: "Invalid server response" }));
  if (!response.ok) throw new Error(data.detail || "Request failed");
  return data;
}

function getUser() {
  try { return JSON.parse(localStorage.getItem("user") || "null"); } catch { return null; }
}
function money(value, currency = "USD") {
  const n = Number(value || 0);
  return new Intl.NumberFormat("en-US", { style: "currency", currency, maximumFractionDigits: 2 }).format(n);
}
function number(value) { return Number(value || 0).toLocaleString(); }
function shortHash(value = "") { return value ? `${value.slice(0, 8)}…${value.slice(-6)}` : "—"; }
function titleCase(value = "") { return value.replaceAll("_", " ").replace(/\b\w/g, c => c.toUpperCase()); }

